'use strict';
let socialAfter=null,socialBusy=false,socialFriends=[],socialIgnores=[],socialTrade=null,socialChannel='',socialFilter='all',socialUnread=0,socialTradeBusy=false,socialSettings={public_mode:'on',private_mode:'on',trade_mode:'on'},socialLastPrivate='',socialStarted=false,socialFinishing=false,tradeWalkingTo=null;
const socialOverheads=new Map(),socialInvitations=new Set(),socialSeenMessages=new Set();
window.playerTrade=false;
const socialRoot=document.createElement('section');socialRoot.id='socialPanel';socialRoot.hidden=true;socialRoot.setAttribute('aria-label','Chat');
socialRoot.innerHTML='<header id="chatTabs"></header><div id="chatPane"><div id="chatMessages" role="log" aria-live="polite"></div><form id="chatForm"><label id="chatChannel" for="chatText">Local:</label><input id="chatText" aria-label="Chat message" maxlength="250" autocomplete="off" placeholder="Press Enter to chat"><button aria-label="Send message" title="Send message">'+gameIcon('next')+'</button></form></div><div id="friendsPane" hidden><form id="friendForm"><input id="friendUsername" aria-label="Player username" maxlength="20" placeholder="Player username"><button>Add friend</button><button type="button" id="ignorePlayer">Ignore</button></form><div id="friendsList"></div><div id="ignoreList"></div></div><p id="socialError" role="status"></p>';
