const chatToggle=document.createElement('button');chatToggle.id='chatToggle';chatToggle.title='Show or hide chat';chatToggle.setAttribute('aria-label','Show or hide chat');chatToggle.innerHTML=gameIcon('chat');document.body.appendChild(chatToggle);
const tradeDialog=document.createElement('dialog');tradeDialog.id='playerTradeDialog';tradeDialog.setAttribute('aria-label','Player trade');document.body.appendChild(tradeDialog);tradeDialog.addEventListener('cancel',e=>{e.preventDefault();tradeAction('cancelTrade');});
function socialButton(text,fn){const b=document.createElement('button');b.type='button';b.textContent=text;b.onclick=fn;return b;}
function socialError(text=''){if(text&&typeof gameMessage==='function')gameMessage(text);$('socialError').textContent=text;const e=$('tradeError');if(e)e.textContent=text;}
function socialContext(element,entries){let timer=0,held=false,start=null;element.addEventListener('contextmenu',e=>{e.preventDefault();showSocialOptions(element,entries());});element.addEventListener('pointerdown',e=>{held=false;start=[e.clientX,e.clientY];if(e.pointerType!=='mouse')timer=setTimeout(()=>{held=true;showSocialOptions(element,entries());},450);});element.addEventListener('pointermove',e=>{if(start&&Math.hypot(e.clientX-start[0],e.clientY-start[1])>8)clearTimeout(timer);});for(const event of ['pointerup','pointercancel','pointerleave'])element.addEventListener(event,()=>clearTimeout(timer));element.addEventListener('click',e=>{if(held){e.preventDefault();e.stopImmediatePropagation();held=false;}},true);}
function showSocialOptions(anchor,entries){document.querySelector('#socialOptions')?.remove();const menu=document.createElement('div');menu.id='socialOptions';menu.setAttribute('role','menu');for(const [text,fn]of entries){const b=socialButton(text,()=>{menu.remove();fn();});b.setAttribute('role','menuitem');menu.appendChild(b);}const host=tradeDialog.open?tradeDialog:document.body;host.appendChild(menu);const r=anchor.getBoundingClientRect(),box=menu.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(r.left,innerWidth-box.width-8))+'px';menu.style.top=Math.max(8,Math.min(r.bottom,innerHeight-box.height-8))+'px';}
document.addEventListener('pointerdown',e=>{if(!e.target.closest?.('#socialOptions'))document.querySelector('#socialOptions')?.remove();});
function applyChatFilter(){for(const p of $('chatMessages').children)p.hidden=socialFilter!=='all'&&p.dataset.channel!==socialFilter;for(const b of $('chatTabs').children)b.setAttribute('aria-pressed',String(b.dataset.channel===socialFilter));}
function addChatLine(text,channel='game',action){const p=document.createElement('p');p.dataset.channel=channel;p.textContent=text;if(action){p.tabIndex=0;p.classList.add('chat-action');p.onclick=action;p.onkeydown=e=>{if(e.key==='Enter')action();};}const log=$('chatMessages'),atEnd=log.scrollHeight-log.scrollTop-log.clientHeight<35;log.appendChild(p);while(log.children.length>100)log.firstElementChild.remove();applyChatFilter();if(atEnd)log.scrollTop=log.scrollHeight;return p;}
function addServiceMessage(text){if(typeof gameMessage==='function')gameMessage(text,{service:true});else{const p=addChatLine(text,'game');p.className='service-message';}}
function appendChat(message){if(socialSeenMessages.has(message.id))return;socialSeenMessages.add(message.id);if(socialSeenMessages.size>250)socialSeenMessages.delete(socialSeenMessages.values().next().value);const outgoing=message.author.toLowerCase()===accountUsername.toLowerCase(),peer=outgoing?message.recipient:message.author,channel=message.recipient?'private':'public';const text=message.recipient?(outgoing?'To ':'From ')+peer+': '+message.body:message.author+': '+message.body;
 const p=addChatLine(text,channel,message.recipient?()=>selectChat(peer):null);if(!outgoing)socialContext(p,()=>[['Message '+message.author,()=>selectChat(message.author)],['Add friend '+message.author,()=>friendAction('friend',message.author)],['Ignore '+message.author,()=>friendAction('ignore',message.author)]]);
 if(message.recipient&&!outgoing)socialLastPrivate=message.author;
 if(!message.recipient&&(message.age??Date.now()-message.created_at)<7000)socialOverheads.set(message.author.toLowerCase(),{text:message.body,until:Date.now()+7000-(message.age??Date.now()-message.created_at)});
 if(socialRoot.hidden){socialUnread++;chatToggle.setAttribute('aria-label','Chat · '+socialUnread+' new messages');chatToggle.classList.add('unread');}}
function openSocial(friends=false){socialRoot.hidden=false;socialUnread=0;chatToggle.classList.remove('unread');$('chatPane').hidden=friends;$('friendsPane').hidden=!friends;if(friends)renderFriends();}
function selectChat(username=''){socialChannel=username;socialFilter=username?'private':'public';openSocial();applyChatFilter();$('chatChannel').textContent=username?'To '+username+':':'Local:';$('chatText').placeholder='';$('chatText').focus();}
function renderChatTabs(){const tabs=$('chatTabs');tabs.replaceChildren();for(const [channel,label]of [['all','All'],['game','Game'],['public','Local'],['private','Private'],['trade','Trade']]){const b=socialButton(label,()=>{socialFilter=channel;if(channel==='public')selectChat();else if(channel==='private'){if(socialChannel||socialLastPrivate)selectChat(socialChannel||socialLastPrivate);else openSocial(true);}else openSocial();applyChatFilter();});b.dataset.channel=channel;if(socialSettings[channel+'_mode']){const mode=document.createElement('small');mode.textContent=socialSettings[channel+'_mode'];b.appendChild(mode);socialContext(b,()=>['on','friends','off'].map(value=>[label+' '+value,()=>setSocialMode(channel,value)]));}tabs.appendChild(b);}const friends=socialButton('Friends',()=>openSocial(true)),close=socialButton('×',()=>socialRoot.hidden=true);close.setAttribute('aria-label','Hide chat');close.title='Hide chat';close.innerHTML=gameIcon('close');tabs.append(friends,close);applyChatFilter();}
async function setSocialMode(channel,value){const next={...socialSettings,[channel+'_mode']:value};try{await socialPost({action:'settings',public:next.public_mode,private:next.private_mode,trade:next.trade_mode});socialSettings=next;renderChatTabs();socialError();}catch(e){socialError(e.message);}}
chatToggle.onclick=()=>{if(socialRoot.hidden)openSocial();else socialRoot.hidden=true;};renderChatTabs();
async function socialPost(body){const r=await fetch('/api/social',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(8000)});const result=await r.json();if(!r.ok)throw new Error(result.error||'Unable to reach other players.');return result;}
$('chatForm').onsubmit=async e=>{e.preventDefault();const input=$('chatText'),text=input.value.trim();if(!text)return;input.disabled=true;try{const sent=await socialPost({action:'message',text,username:socialChannel||undefined});if(sent.message)appendChat(sent.message);input.value='';socialError();await pollSocial();}catch(e){socialError(e.message);}finally{input.disabled=false;input.focus();}};
$('friendForm').onsubmit=async e=>{e.preventDefault();await friendAction('friend',$('friendUsername').value.trim());};$('ignorePlayer').onclick=()=>friendAction('ignore',$('friendUsername').value.trim());
async function friendAction(action,username){try{await socialPost({action,username});socialError();$('friendUsername').value='';await pollSocial();}catch(e){socialError(e.message);}}
function renderFriends(){const list=$('friendsList');list.replaceChildren();if(!socialFriends.length){const p=document.createElement('p');p.textContent='Your friends list is empty.';list.appendChild(p);}for(const f of socialFriends){const row=document.createElement('div'),name=socialButton(f.username,()=>selectChat(f.username)),status=document.createElement('span');name.className=f.online?'friend-online':'friend-offline';status.textContent=f.online?'Online':'Offline';socialContext(name,()=>[['Message '+f.username,()=>selectChat(f.username)],['Remove friend '+f.username,()=>friendAction('removeFriend',f.username)]]);row.append(name,status,socialButton('Remove',()=>friendAction('removeFriend',f.username)));list.appendChild(row);}const ignored=$('ignoreList');ignored.replaceChildren();for(const name of socialIgnores){const row=document.createElement('div');row.textContent='Ignored: '+name;row.appendChild(socialButton('Remove',()=>friendAction('removeIgnore',name)));ignored.appendChild(row);}}
function tradeCombatActive(){const o=activeEncounter?.o;return !!(o&&activeEncounter.scene===currentScene&&o.hp>0&&o.dead<=time&&!o._returning||playerAttackMotion&&time-lastAttack<(playerAttackMotion.duration||1.4)||meleeImpacts.some(hit=>!hit.enemy)||projectiles.some(p=>p.scene===currentScene));}
async function preparePlayerTrade(){if(window.playerTrade)return;if(tradeCombatActive())throw new Error('Finish combat before trading.');if($('modal').open||$('creator').open||$('spiritsDialog').open)throw new Error('Close the current interface before trading.');stop();window.playerTrade=true;queueCloudSave();const deadline=Date.now()+6500;while(cloudBusy&&Date.now()<deadline)await new Promise(r=>setTimeout(r,50));await flushCloudSave();if(cloudBusy||cloudDirty||cloudDisconnected||cloudConflict){window.playerTrade=false;throw new Error('Unable to save your character for trading.');}}
async function requestPlayerTrade(username){if(socialTradeBusy||window.playerTrade)return;const peer=[...onlinePeers.values()].find(p=>p.username?.toLowerCase()===username.toLowerCase());if(peer&&Math.hypot(peer.x-px,peer.y-py)>2){stop();tradeWalkingTo=username;toast('Walking to '+peer.name+' to trade.');return;}
 socialTradeBusy=true;try{await preparePlayerTrade();if(socialTrade?.status==='pending'&&socialTrade.incoming&&socialTrade.username.toLowerCase()===username.toLowerCase()){socialTradeBusy=false;await tradeAction('acceptTrade');return;}const result=await socialPost({action:'requestTrade',username});socialTrade=result.trade;window.playerTrade=socialTrade.status==='active';if(socialTrade.status==='pending')addChatLine('Sending trade request to '+username+'…','trade',()=>{if(socialTrade?.username===username&&socialTrade.status==='pending')tradeAction('cancelTrade');});renderPlayerTrade();socialError();}catch(e){window.playerTrade=false;socialError(e.message);toast(e.message);}finally{socialTradeBusy=false;}}
function updateTradeApproach(){if(!tradeWalkingTo)return;const username=tradeWalkingTo,peer=[...onlinePeers.values()].find(p=>p.username===username);if(!peer||onlineScene!==currentScene){tradeWalkingTo=null;return;}if(Math.hypot(peer.x-px,peer.y-py)<=2){tradeWalkingTo=null;requestPlayerTrade(username);return;}if(!path.length){const next=route(peer.x,peer.y,true,1.5);if(next===null){tradeWalkingTo=null;toast('You cannot reach that player.');}else path=next;}}
async function tradeAction(action,offer){if(!socialTrade||socialTradeBusy)return;if(action==='acceptTrade'){const peer=[...onlinePeers.values()].find(p=>p.username===socialTrade.username);if(peer&&Math.hypot(peer.x-px,peer.y-py)>2){stop();tradeWalkingTo=peer.username;return;}}socialTradeBusy=true;try{if(action==='acceptTrade')await preparePlayerTrade();const r=await socialPost({action,id:socialTrade.id,revision:socialTrade.revision,offer});socialTrade=r.trade;await renderPlayerTrade();socialError();}catch(e){if(socialTrade?.status==='pending')window.playerTrade=false;await pollSocial();socialError(e.message);}finally{socialTradeBusy=false;}}
function offerSummary(offer){return [...(offer.gold?[offer.gold.toLocaleString()+' coins']:[]),...offer.items.map(e=>(ITEMS[e.id]?.name||e.id)+' × '+e.count.toLocaleString())];}
function tradeItemButton(id,count,action){const b=socialButton('',action);b.className='trade-item';b.title=(id==='coins'?'Coins':ITEMS[id]?.name||id)+' × '+count.toLocaleString();b.setAttribute('aria-label',b.title);b.appendChild(itemCanvas(id,64));const n=document.createElement('span');n.className='trade-count';n.textContent=count>=1000000?(count/1000000).toFixed(1)+'M':count>=100000?Math.floor(count/1000)+'K':count.toLocaleString();b.appendChild(n);return b;}
function changeTradeQuantity(id,count,remove=false){if(ITEMS[id]?.tradeable===false){toast('This item is bound to your character.');return;}const t=socialTrade;if(!t||t.stage==='review'||!Number.isSafeInteger(count)||count<=0)return;const mine=t.mine,existing=id==='coins'?mine.gold:mine.items.find(e=>e.id===id)?.count||0,maximum=spareItemCount(id),next=Math.max(0,Math.min(maximum,existing+(remove?-count:count))),items=mine.items.filter(e=>e.id!==id);if(id!=='coins'&&next)items.push({id,count:next});tradeAction('offer',{gold:id==='coins'?next:mine.gold,items:id==='coins'?mine.items:items});}
function quantityOptions(id,available,remove=false){const verb=remove?'Remove':'Offer';return [...[1,5,10].map(n=>[verb+' '+n,()=>changeTradeQuantity(id,n,remove)]),[verb+' All',()=>changeTradeQuantity(id,available,remove)],[verb+' X',()=>askTradeQuantity(id,available,remove)]];}
function askTradeQuantity(id,available,remove){document.querySelector('#tradeQuantity')?.remove();const form=document.createElement('form');form.id='tradeQuantity';const label=document.createElement('label');label.textContent=(remove?'Remove':'Offer')+' how many? ';const input=document.createElement('input');input.type='number';input.min=1;input.max=available;input.step=1;input.required=true;input.setAttribute('aria-label','Quantity');label.appendChild(input);const submit=document.createElement('button');submit.textContent='Done';form.append(label,submit,socialButton('Cancel',()=>form.remove()));form.onsubmit=e=>{e.preventDefault();const n=Number(input.value);if(Number.isSafeInteger(n)&&n>0){form.remove();changeTradeQuantity(id,Math.min(n,available),remove);}};tradeDialog.appendChild(form);input.focus();}
async function finishPlayerTrade(t){if(socialFinishing)return;socialFinishing=true;try{if(t.status==='complete'){clearTimeout(cloudTimer);while(cloudBusy)await new Promise(r=>setTimeout(r,30));cloudDirty=false;await initializeCloud();renderUI();}tradeDialog.close();window.playerTrade=false;socialTrade=null;addChatLine(t.status==='complete'?'Accepted trade.':'Trade declined.','trade');}catch{pauseForServer('Reconnect your character','The trade is saved. Reconnect to load your items.');}finally{socialFinishing=false;}}
async function renderPlayerTrade(){const t=socialTrade;if(!t)return;if(['complete','cancelled'].includes(t.status)){await finishPlayerTrade(t);return;}
 if(t.status==='pending'){if(t.incoming&&!socialInvitations.has(t.id)){socialInvitations.add(t.id);addChatLine(t.username+' wishes to trade with you.','trade',()=>{if(socialTrade?.id===t.id&&socialTrade.status==='pending')tradeAction('acceptTrade');else socialError('That trade request has expired.');});chatToggle.classList.add('unread');}return;}
 if(!window.playerTrade){stop();window.playerTrade=true;}
 const quantityForm=document.querySelector('#tradeQuantity');if(!tradeDialog.open)tradeDialog.showModal();tradeDialog.replaceChildren();const title=document.createElement('h2');title.textContent=t.stage==='review'?'Are you sure you want to make this trade?':'Trading with: '+t.username;tradeDialog.appendChild(title);
 const layout=document.createElement('div');layout.className='trade-layout';const columns=document.createElement('div');columns.className='trade-offers';
 for(const [heading,offer,mine]of [['You give',t.mine,true],[t.username+' gives',t.theirs,false]]){const section=document.createElement('section'),h=document.createElement('h3');h.textContent=heading;section.appendChild(h);if(t.stage==='review'){const lines=offerSummary(offer);for(const text of lines.length?lines:['Absolutely nothing!']){const p=document.createElement('p');p.textContent=text;section.appendChild(p);}}else{const grid=document.createElement('div');grid.className='trade-grid';for(const e of [...(offer.gold?[{id:'coins',count:offer.gold}]:[]),...offer.items]){const b=tradeItemButton(e.id,e.count,mine?()=>changeTradeQuantity(e.id,1,true):()=>{});if(mine)socialContext(b,()=>quantityOptions(e.id,e.count,true));grid.appendChild(b);}section.appendChild(grid);}columns.appendChild(section);}layout.appendChild(columns);
 if(t.stage!=='review'){const bag=document.createElement('section'),h=document.createElement('h3');h.textContent='Inventory';bag.className='trade-bag';bag.appendChild(h);const grid=document.createElement('div');grid.className='trade-grid';for(const [id,item]of Object.entries(ITEMS)){if(item.tradeable===false)continue;const offered=id==='coins'?t.mine.gold:t.mine.items.find(e=>e.id===id)?.count||0,n=(spareItemCount(id))-offered;if(n<=0)continue;const b=tradeItemButton(id,n,()=>changeTradeQuantity(id,1));socialContext(b,()=>quantityOptions(id,n));grid.appendChild(b);}bag.appendChild(grid);layout.appendChild(bag);}tradeDialog.appendChild(layout);
 const status=document.createElement('p');status.className='trade-status';const accepted=t.stage==='review'?t.confirmed:t.accepted,peerAccepted=t.stage==='review'?t.peerConfirmed:t.peerAccepted;status.textContent=accepted?'Waiting for other player…':peerAccepted?'Other player has accepted.':t.stage==='review'?'Check the quantities carefully. This is the final confirmation.':'Check the offer before accepting.';const accept=socialButton(accepted?'Accepted':'Accept',()=>tradeAction(t.stage==='review'?'confirmTrade':'acceptOffer'));accept.disabled=accepted;const actions=document.createElement('footer');actions.append(accept,socialButton('Decline',()=>tradeAction('cancelTrade')));const error=document.createElement('p');error.id='tradeError';error.setAttribute('role','alert');tradeDialog.append(status,actions,error);paintItemIcons(tradeDialog);if(quantityForm&&t.stage!=='review')tradeDialog.appendChild(quantityForm);
}
async function pollSocial(){if(socialBusy||!cloudReady||!assetsReady||cloudDisconnected||!s.character)return;socialBusy=true;try{const r=await fetch('/api/social?'+(socialAfter===null?'':'after='+socialAfter)+(socialTrade?'&trade='+encodeURIComponent(socialTrade.id):''),{cache:'no-store',signal:AbortSignal.timeout(5000)});if(!r.ok)return;const data=await r.json();if(!socialStarted){socialStarted=true;openSocial();if(typeof flushGameMessages==='function')flushGameMessages();}for(const m of data.messages){if(m.id>(socialAfter??0))appendChat(m);}socialAfter=Math.max(socialAfter??0,data.cursor||0,...data.messages.map(m=>m.id));socialFriends=data.friends;socialIgnores=data.ignores||[];if(data.settings&&JSON.stringify(data.settings)!==JSON.stringify(socialSettings)){socialSettings=data.settings;renderChatTabs();}if(!$('friendsPane').hidden)renderFriends();if(data.trade&&(data.trade.id!==socialTrade?.id||data.trade.revision>socialTrade?.revision)){socialTrade=data.trade;await renderPlayerTrade();}}catch{}finally{socialBusy=false;}}
setInterval(pollSocial,750);
document.addEventListener('keydown',e=>{if(e.target.closest?.('input,textarea,select,button,dialog,[contenteditable]')){if(e.key==='Escape'&&e.target===$('chatText')){socialChannel='';$('chatChannel').textContent='Local:';e.target.blur();}return;}if(cloudDisconnected||!assetsReady)return;if(e.key==='Enter'){e.preventDefault();selectChat(socialChannel);}else if(e.key==='Tab'&&socialLastPrivate){e.preventDefault();selectChat(socialLastPrivate);}});

function pushOverheadChat(labels,text,x,y){const words=text.match(/.{1,38}(?:\s|$)|.{1,38}/g)||[text];for(let i=0;i<words.length;i++)labels.push([words[i].trim(),x+.5,2.85+(words.length-i-1)*.33,y+.5,'#ffff00']);}
